H.background();
let pC = Math.max(0, Math.min(100, P.pctC));
let pH = Math.max(0, Math.min(100, P.pctH));
if (pC + pH > 100) { const s = 100 / (pC + pH); pC *= s; pH *= s; }
const pO = Math.max(0, 100 - pC - pH);
const MC = 12.011, MH = 1.008, MO = 15.999;
const nC = pC / MC, nH = pH / MH, nO = pO / MO;
const mins = Math.min(nC > 0 ? nC : Infinity, nH > 0 ? nH : Infinity, nO > 0 ? nO : Infinity);
const base = isFinite(mins) && mins > 0 ? mins : 1;
const rC = nC / base, rH = nH / base, rO = nO / base;
H.text("Empirical formula: divide moles by the smallest", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Take a 100 g sample so mass% = grams; convert to moles, then scale to smallest whole ratio.", 24, 52, { color: H.colors.sub, size: 13 });

const elems = [
  { sym: "C", pct: pC, n: nC, r: rC, col: H.colors.accent },
  { sym: "H", pct: pH, n: nH, r: rH, col: H.colors.good },
  { sym: "O", pct: pO, n: nO, r: rO, col: H.colors.violet }
];
const hi = Math.floor((t * 0.6) % 3);
